function countdown(n) {
  if (n === 0) return ["liftoff"];    // base case
  return [n, ...countdown(n - 1)];    // recursive case: smaller n
}
countdown(3); // [3, 2, 1, "liftoff"]

// Flatten a list that may contain lists
function flatten(items) {
  const out = [];
  for (const item of items) {
    if (Array.isArray(item)) out.push(...flatten(item)); // go one level deeper
    else out.push(item);
  }
  return out;
}
flatten([1, [2, [3, [4]]]]); // [1, 2, 3, 4]

// How deep is a tree of { children: [...] }?
function depth(node) {
  if (node.children.length === 0) return 1;
  return 1 + Math.max(...node.children.map(depth));
}

function sumDown(n) {
  if (n === 0) return 0;
  return n + sumDown(n - 1);
}
sumDown(3); // 3 + 2 + 1 + 0 = 6
